extern int _orbit_argc;

int main(int argc, char* argv[]) {
    _orbit_argv = argv;
    _orbit_argc = argc;
    
#ifdef _WIN32
    HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);
    if (hOut != INVALID_HANDLE_VALUE) {
        DWORD dwMode = 0;
        if (GetConsoleMode(hOut, &dwMode)) {
            SetConsoleMode(hOut, dwMode | 0x0001 | 0x0004);
        }
        SetConsoleOutputCP(65001);
    }
#endif
    
    orbit_ledger_enable_file_dump();
    orbit_string_pool_init(2048);
    OrbitArena* arena = orbit_arena_create(131072);

    int _orbit_exit_code = orbit_main(arena);

    orbit_arena_destroy(arena);
    orbit_string_pool_cleanup();
    
    return _orbit_exit_code;
}
